        Scanner scanner = new Scanner(System.in);
        StringBuilder sb = new StringBuilder();
        while (scanner.hasNext()) {
            sb.append(scanner.next());
        }
        String all = sb.toString();
        int[][] board = new int[4][4];
        int idx = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (idx < all.length()) {
                    char c = all.charAt(idx++);
                    if (c == 'x') board[i][j] = 1;
                    else if (c == 'o') board[i][j] = -3;
                    else board[i][j] = 0;
                } else {
                    board[i][j] = 0;
                }
            }
        }

        boolean canWin = false;
        for (int i = 0; !canWin && i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (board[i][j] >= 0) {
                    int sumHor = 0, sumDiaUp = 0, sumDiaDown = 0, sumVer = 0;
                    if (j < 2)
                        sumHor = board[i][j] + board[i][j+1] + board[i][j+2];
                    if (i < 2)
                        sumVer = board[i][j] + board[i+1][j] + board[i+2][j];
                    if (i < 2 && j < 2)
                        sumDiaUp = board[i][j] + board[i+1][j+1] + board[i+2][j+2];
                    if (i >= 2 && j < 2)
